import java.time.LocalDate;import java.util.Scanner;public class LibraryConsole{public static void main(String[]a){var l=new Library();try(var s=new Scanner(System.in)){System.out.println("1 add book | 2 add DVD | 3 register | 4 borrow | 5 return | 6 overdue | 7 search | 0 exit");while(s.hasNextLine()){String c=s.nextLine().trim();if(c.equals("0"))break;try{switch(c){case"1"->l.addItem(new Book(s.nextLine(),s.nextLine(),s.nextLine(),s.nextLine()));case"2"->l.addItem(new Dvd(s.nextLine(),s.nextLine(),Integer.parseInt(s.nextLine())));case"3"->l.registerMember(new Member(s.nextLine(),s.nextLine()));case"4"->System.out.println(l.borrow(s.nextLine(),s.nextLine()));case"5"->l.giveBack(s.nextLine(),s.nextLine(),LocalDate.now());case"6"->System.out.println(l.overdueItems(LocalDate.now()));case"7"->System.out.println(l.searchByTitle(s.nextLine()));default->System.out.println("Unknown choice");}}catch(Exception e){System.out.println("Error: "+e.getMessage());}}}}}
